export class GlpiFormDestinationConditionController{constructor(){this.#t()}#t(){document.addEventListener("updated_strategy",t=>{if(t.detail&&t.detail.container){const n=$(t.detail.container).closest(".accordion-item");if(n.length>0){this.#n(n,t.detail.strategy)}}});document.addEventListener("conditions_count_changed",t=>{this.#e($(t.detail.container).closest(".accordion-item"),t.detail.conditions_count)});const t=document.querySelectorAll("[data-glpi-destination-click-on-space]");for(const n of t){n.addEventListener("keyup",t=>{if(t.key==" "&&t.target.tagName!=="INPUT"){n.dispatchEvent(new Event("click"))}})}}#n(t,n){t.find("[data-glpi-editor-condition-badge]").removeClass("d-flex").addClass("d-none");t.find(`[data-glpi-editor-condition-badge=${n}]`).removeClass("d-none").addClass("d-flex")}#e(t,n){t.find("[data-glpi-editor-conditions-count-badge]").html(n)}}